{
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Write|Edit",
        "hooks": [
          {
            "type": "command",
            "command": "scripts/harness-advisory.sh",
            "timeout": 120
          }
        ]
      }
    ]
  }
}

